cd /home/hera/measurements/zack/20260822-vti-02 && for i in 5 6 7; do echo "== run $i"; python3 -c "
import json; m=json.load(open('data/$i/metadata.json'))
for k in ['comments','columns','measurement_config','type','function','delay','param','setpoints','slow_param','fast_param','slow_delay','fast_delay']:
    if k in m:
        v=m[k]
        if isinstance(v,list) and len(v)>12: v=f'[{v[0]}, {v[1]}, ..., {v[-1]}] (n={len(v)})'
        print(k, '=', v)
print('dur_min', (m['end_time']-m['start_time'])/60)
"; done; echo; hera-watch data/6 --once 2>&1 | tail -40; echo; hera-watch data/7 --once 2>&1 | tail -40

